# EVOLVE-BLOCK-START
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
// #include <map> 
// #include <set>  
#include <queue>
#include <cmath> 
#include <iomanip> 
#include <limits> 

// --- Constants ---
constexpr int GRID_SIZE = 30;
constexpr int NUM_TURNS = 300;
constexpr int INF = std::numeric_limits<int>::max(); 

struct Point {
    int r, c;

    bool operator==(const Point& other) const { return r == other.r && c == other.c; }
    bool operator!=(const Point& other) const { return !(*this == other); }
    bool operator<(const Point& other) const { 
        if (r != other.r) return r < other.r;
        return c < other.c;
    }
};
const Point INVALID_POINT = {-1, -1};


// Tunable parameters
constexpr int STAND_OUTSIDE_INNER_SAFE_PENALTY = 1000; 
constexpr int ADJACENT_WALL_PRIORITY_BONUS = 0; 
constexpr int NEAR_PET_PENALTY_POINTS_PER_PET = 0; 
constexpr int NEAR_PET_RADIUS = 2; 
constexpr int MAX_STUCK_TURNS = 10; // Slightly increased

// Directions: Up, Down, Left, Right (indices 0, 1, 2, 3)
const Point DIRS[4] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}; 
const char DIR_CHARS_BUILD[4] = {'u', 'd', 'l', 'r'}; 
const char DIR_CHARS_MOVE[4] = {'U', 'D', 'L', 'R'};   
const char PET_MOVE_CHARS[4] = {'U', 'D', 'L', 'R'}; 

struct PetInfo {
    Point pos;
    int type; 
    int id;
};

enum class HumanObjective { 
    BUILDING_WALLS, 
    GOING_TO_SAFE_SPOT, 
    STAYING_IN_SAFE_SPOT, 
    REPOSITIONING_STUCK
    // FLEEING_PET_IN_PEN removed, simplified objective setting
};

struct HumanInfo {
    Point pos;
    int id;

    int strip_r_start; 
    int strip_r_end;   

    Point inner_safe_ul;     
    Point inner_safe_br;     
    Point final_stand_pos;  

    std::vector<Point> assigned_wall_cells; 
    HumanObjective objective; 
    int turns_stuck_building = 0; 
};

// --- Game Grid and State ---
bool is_impassable_grid_static[GRID_SIZE + 1][GRID_SIZE + 1]; 
std::vector<PetInfo> pets_global_state;
std::vector<HumanInfo> humans_global_state;
int N_pets_global, M_humans_global;

Point bfs_parent_grid[GRID_SIZE + 1][GRID_SIZE + 1];
bool bfs_visited_grid[GRID_SIZE + 1][GRID_SIZE + 1];


// --- Utility Functions ---
bool is_valid_coord(int val) {
    return val >= 1 && val <= GRID_SIZE;
}

bool is_valid_point(Point p) {
    return is_valid_coord(p.r) && is_valid_coord(p.c);
}

int manhattan_distance(Point p1, Point p2) {
    if (!is_valid_point(p1) || !is_valid_point(p2)) return INF;
    return std::abs(p1.r - p2.r) + std::abs(p1.c - p2.c);
}

// Computes shortest walking distances from one human while respecting built walls.
std::vector<std::vector<int>> compute_distance_field(Point start_pos) {
    std::vector<std::vector<int>> dist(
        GRID_SIZE + 1, std::vector<int>(GRID_SIZE + 1, INF)
    );
    if (!is_valid_point(start_pos) ||
        is_impassable_grid_static[start_pos.r][start_pos.c]) {
        return dist;
    }

    std::queue<Point> q;
    q.push(start_pos);
    dist[start_pos.r][start_pos.c] = 0;

    while (!q.empty()) {
        Point cur = q.front();
        q.pop();

        for (int d = 0; d < 4; ++d) {
            Point nxt = {cur.r + DIRS[d].r, cur.c + DIRS[d].c};
            if (!is_valid_point(nxt) ||
                is_impassable_grid_static[nxt.r][nxt.c] ||
                dist[nxt.r][nxt.c] != INF) {
                continue;
            }
            dist[nxt.r][nxt.c] = dist[cur.r][cur.c] + 1;
            q.push(nxt);
        }
    }
    return dist;
}

int count_adjacent_walls_or_boundaries(Point p) {
    int count = 0;
    for (int i = 0; i < 4; ++i) {
        Point neighbor = {p.r + DIRS[i].r, p.c + DIRS[i].c};
        if (!is_valid_point(neighbor) || (is_valid_point(neighbor) && is_impassable_grid_static[neighbor.r][neighbor.c])) {
            count++;
        }
    }
    return count;
}

bool can_theoretically_build_at(Point wall_pos, int builder_human_id) {
    // Accept only wall cells that are currently buildable and satisfy pet/human restrictions.
    if (!is_valid_point(wall_pos)) return false;
    if (is_impassable_grid_static[wall_pos.r][wall_pos.c]) return false; 

    for (const auto& pet : pets_global_state) {
        if (pet.pos == wall_pos) return false; 
        if (manhattan_distance(wall_pos, pet.pos) == 1) return false; 
    }

    for (const auto& human : humans_global_state) { 
        if (human.id == builder_human_id) continue; // Builder themself can be adjacent
        if (human.pos == wall_pos) return false; // Other human on the wall_pos
    }
    return true;
}

char get_bfs_move_char(Point start_pos, Point target_pos, 
                       const std::vector<Point>& current_turn_tentative_walls) {
    if (start_pos == target_pos) return '.';

    std::queue<Point> q;
    q.push(start_pos);

    for(int r_bfs = 1; r_bfs <= GRID_SIZE; ++r_bfs) for(int c_bfs = 1; c_bfs <= GRID_SIZE; ++c_bfs) {
        bfs_visited_grid[r_bfs][c_bfs] = false;
        bfs_parent_grid[r_bfs][c_bfs] = INVALID_POINT;
    }
    if (!is_valid_point(start_pos)) return '.'; 
    bfs_visited_grid[start_pos.r][start_pos.c] = true;

    Point path_found_dest = INVALID_POINT; 

    while(!q.empty()){
        Point curr = q.front();
        q.pop();

        for(int i_dir=0; i_dir < 4; ++i_dir){ 
            Point next_p = {curr.r + DIRS[i_dir].r, curr.c + DIRS[i_dir].c};

            if(is_valid_point(next_p) && 
               !is_impassable_grid_static[next_p.r][next_p.c] && 
               !bfs_visited_grid[next_p.r][next_p.c]){

                bool is_tentative_wall_conflict = false;
                for(const auto& tw : current_turn_tentative_walls) {
                    if(next_p == tw) {
                        is_tentative_wall_conflict = true;
                        break;
                    }
                }
                if(is_tentative_wall_conflict) continue;

                bfs_visited_grid[next_p.r][next_p.c] = true;
                bfs_parent_grid[next_p.r][next_p.c] = curr;

                if (next_p == target_pos) { 
                    path_found_dest = next_p; 
                    goto bfs_done_label; 
                } 
                q.push(next_p);
            }
        }
    }

bfs_done_label:; 
    if (path_found_dest.r == -1) return '.'; 

    Point current_step_in_path = path_found_dest;
    while(!(bfs_parent_grid[current_step_in_path.r][current_step_in_path.c] == INVALID_POINT) &&
          !(bfs_parent_grid[current_step_in_path.r][current_step_in_path.c] == start_pos)) {
        current_step_in_path = bfs_parent_grid[current_step_in_path.r][current_step_in_path.c];
    }

    for(int i_dir = 0; i_dir < 4; ++i_dir){ 
        if(start_pos.r + DIRS[i_dir].r == current_step_in_path.r && 
           start_pos.c + DIRS[i_dir].c == current_step_in_path.c){
            return DIR_CHARS_MOVE[i_dir];
        }
    }
    return '.'; 
}


void initialize_game() {
    std::cin >> N_pets_global;
    pets_global_state.resize(N_pets_global);
    for (int i = 0; i < N_pets_global; ++i) {
        pets_global_state[i].id = i;
        std::cin >> pets_global_state[i].pos.r >> pets_global_state[i].pos.c >> pets_global_state[i].type;
    }

    std::cin >> M_humans_global;
    humans_global_state.resize(M_humans_global);

    for(int r_grid=0; r_grid <= GRID_SIZE; ++r_grid) for(int c_grid=0; c_grid <= GRID_SIZE; ++c_grid) is_impassable_grid_static[r_grid][c_grid] = false;

    for (int i = 0; i < M_humans_global; ++i) {
        humans_global_state[i].id = i;
        std::cin >> humans_global_state[i].pos.r >> humans_global_state[i].pos.c;
    }

    auto evaluate_layout = [&](bool vertical) {
        /* Evaluates one orientation by separator risk and final reachable component area. */
        int base = GRID_SIZE / M_humans_global;
        int rem = GRID_SIZE % M_humans_global;
        std::vector<int> lo(M_humans_global), hi(M_humans_global);
        int cur = 1;

        for (int i = 0; i < M_humans_global; ++i) {
            int len = base + (i < rem ? 1 : 0);
            lo[i] = cur;
            hi[i] = cur + len - 1;
            cur = hi[i] + 1;
        }

        bool blocked[GRID_SIZE + 1][GRID_SIZE + 1] = {};
        for (int i = 0; i + 1 < M_humans_global; ++i) {
            int cut = hi[i];
            if (!vertical) {
                for (int c = 1; c <= GRID_SIZE; ++c) blocked[cut][c] = true;
            } else {
                for (int r = 1; r <= GRID_SIZE; ++r) blocked[r][cut] = true;
            }
        }

        long long score = 0;
        for (int i = 0; i < M_humans_global; ++i) {
            const Point hp = humans_global_state[i].pos;
            int separator_distance = INF;

            for (int j = 0; j + 1 < M_humans_global; ++j) {
                int cut = hi[j];
                separator_distance = std::min(
                    separator_distance,
                    vertical ? std::abs(hp.c - cut) : std::abs(hp.r - cut)
                );
            }
            if (separator_distance == INF) separator_distance = 0;
            // Construction time is dominated by the initial travel needed
            // to reach a separator.  Give this term enough weight that the
            // orientation selector prefers layouts whose cuts are naturally
            // close to the humans, without adding extra pet heuristics.
            score += 48LL * separator_distance;

            // Add a modest risk estimate for pets approaching the separators.
            // The construction becomes harder when a pet starts directly on,
            // or immediately beside, one of the planned cuts.
            for (int j = 0; j + 1 < M_humans_global; ++j) {
                int cut = hi[j];
                int separator_distance =
                    vertical ? std::abs(hp.c - cut)
                              : std::abs(hp.r - cut);

                int nearest_pet_to_cut = INF;
                for (const PetInfo& pet : pets_global_state) {
                    int pet_cut_distance =
                        vertical ? std::abs(pet.pos.c - cut)
                                  : std::abs(pet.pos.r - cut);
                    nearest_pet_to_cut =
                        std::min(nearest_pet_to_cut, pet_cut_distance);
                }

                // Only count pets close enough to plausibly interfere during
                // the early construction phase.  Keep the weights small so
                // layout selection remains primarily geometry-driven.
                if (nearest_pet_to_cut == 0) {
                    score += 18 + separator_distance;
                } else if (nearest_pet_to_cut == 1) {
                    score += 8;
                } else if (nearest_pet_to_cut == 2) {
                    score += 2;
                }
            }

            bool seen[GRID_SIZE + 1][GRID_SIZE + 1] = {};
            std::queue<Point> q;
            if (is_valid_point(hp) && !blocked[hp.r][hp.c]) {
                q.push(hp);
                seen[hp.r][hp.c] = true;
            }

            int area = 0;
            while (!q.empty()) {
                Point p = q.front();
                q.pop();
                ++area;

                for (int d = 0; d < 4; ++d) {
                    Point nxt = {p.r + DIRS[d].r, p.c + DIRS[d].c};
                    if (!is_valid_point(nxt) || seen[nxt.r][nxt.c] ||
                        blocked[nxt.r][nxt.c]) {
                        continue;
                    }
                    seen[nxt.r][nxt.c] = true;
                    q.push(nxt);
                }
            }

            score -= 3LL * area;
        }

        return score;
    };

    bool use_vertical = evaluate_layout(true) < evaluate_layout(false);

    int base_strip_size = GRID_SIZE / M_humans_global;
    int remainder = GRID_SIZE % M_humans_global;
    int current_begin = 1;

    for (int i = 0; i < M_humans_global; ++i) {
        HumanInfo& human = humans_global_state[i];
        int len = base_strip_size + (i < remainder ? 1 : 0);
        int lo = current_begin;
        int hi = lo + len - 1;
        current_begin = hi + 1;

        human.assigned_wall_cells.clear();

        if (!use_vertical) {
            human.strip_r_start = lo;
            human.strip_r_end = hi;
            human.inner_safe_ul = {lo + (len >= 3 ? 1 : 0), 2};
            human.inner_safe_br = {hi - (len >= 3 ? 1 : 0), GRID_SIZE - 1};

            if (i > 0) {
                for (int c = GRID_SIZE / 2 + 1; c <= GRID_SIZE; ++c)
                    human.assigned_wall_cells.push_back({lo, c});
            }
            if (i + 1 < M_humans_global) {
                for (int c = 1; c <= GRID_SIZE / 2; ++c)
                    human.assigned_wall_cells.push_back({hi, c});
            }
        } else {
            human.strip_r_start = 1;
            human.strip_r_end = GRID_SIZE;
            human.inner_safe_ul = {2, lo + (len >= 3 ? 1 : 0)};
            human.inner_safe_br = {GRID_SIZE - 1, hi - (len >= 3 ? 1 : 0)};

            if (i > 0) {
                for (int r = GRID_SIZE / 2 + 1; r <= GRID_SIZE; ++r)
                    human.assigned_wall_cells.push_back({r, lo});
            }
            if (i + 1 < M_humans_global) {
                for (int r = 1; r <= GRID_SIZE / 2; ++r)
                    human.assigned_wall_cells.push_back({r, hi});
            }
        }

        human.inner_safe_ul.r = std::max(1, human.inner_safe_ul.r);
        human.inner_safe_ul.c = std::max(1, human.inner_safe_ul.c);
        human.inner_safe_br.r = std::min(GRID_SIZE, human.inner_safe_br.r);
        human.inner_safe_br.c = std::min(GRID_SIZE, human.inner_safe_br.c);

        if (human.inner_safe_ul.r > human.inner_safe_br.r)
            human.inner_safe_br.r = human.inner_safe_ul.r;
        if (human.inner_safe_ul.c > human.inner_safe_br.c)
            human.inner_safe_br.c = human.inner_safe_ul.c;

        human.final_stand_pos = {
            (human.inner_safe_ul.r + human.inner_safe_br.r) / 2,
            (human.inner_safe_ul.c + human.inner_safe_br.c) / 2
        };

        std::sort(human.assigned_wall_cells.begin(),
                  human.assigned_wall_cells.end());
        human.assigned_wall_cells.erase(
            std::unique(human.assigned_wall_cells.begin(),
                        human.assigned_wall_cells.end()),
            human.assigned_wall_cells.end());
    }
}

/* Flood-fills the human's current terminal component and moves toward a
   deterministic interior cell maximizing minimum distance from all pets. */
char move_to_best_terminal_component(const HumanInfo& human,
                                     const std::vector<Point>& tentative_walls) {
    bool blocked[GRID_SIZE + 1][GRID_SIZE + 1] = {};
    for (const Point& wall : tentative_walls) {
        if (is_valid_point(wall)) blocked[wall.r][wall.c] = true;
    }

    if (!is_valid_point(human.pos) ||
        is_impassable_grid_static[human.pos.r][human.pos.c] ||
        blocked[human.pos.r][human.pos.c]) {
        return '.';
    }

    bool seen[GRID_SIZE + 1][GRID_SIZE + 1] = {};
    std::vector<Point> component;
    std::queue<Point> q;
    q.push(human.pos);
    seen[human.pos.r][human.pos.c] = true;

    while (!q.empty()) {
        Point cur = q.front();
        q.pop();
        component.push_back(cur);

        for (int d = 0; d < 4; ++d) {
            Point nxt = {cur.r + DIRS[d].r, cur.c + DIRS[d].c};
            if (!is_valid_point(nxt) ||
                seen[nxt.r][nxt.c] ||
                is_impassable_grid_static[nxt.r][nxt.c] ||
                blocked[nxt.r][nxt.c]) {
                continue;
            }
            seen[nxt.r][nxt.c] = true;
            q.push(nxt);
        }
    }

    if (component.empty()) return '.';

    Point target = component.front();
    int best_clearance = -1;
    int best_center_distance = INF;

    int center_r = (human.inner_safe_ul.r + human.inner_safe_br.r) / 2;
    int center_c = (human.inner_safe_ul.c + human.inner_safe_br.c) / 2;

    for (const Point& cell : component) {
        int clearance = INF;
        for (const PetInfo& pet : pets_global_state) {
            clearance = std::min(clearance, manhattan_distance(cell, pet.pos));
        }

        int center_distance =
            std::abs(cell.r - center_r) + std::abs(cell.c - center_c);

        if (clearance > best_clearance ||
            (clearance == best_clearance &&
             (center_distance < best_center_distance ||
              (center_distance == best_center_distance && cell < target)))) {
            best_clearance = clearance;
            best_center_distance = center_distance;
            target = cell;
        }
    }

    return get_bfs_move_char(human.pos, target, tentative_walls);
}

std::string decide_human_actions() {
    // Greedily build assigned separators, preferring reachable and pet-safe standing cells.
    std::string actions_str(M_humans_global, '.');
    std::vector<Point> tentative_walls_this_turn; 
    std::vector<Point> tentative_move_targets_this_turn(M_humans_global, INVALID_POINT); 

    for (int i = 0; i < M_humans_global; ++i) {
        HumanInfo& human = humans_global_state[i];

        int unbuilt_walls_count = 0;
        for (const auto& wall_cell : human.assigned_wall_cells) {
            if (is_valid_point(wall_cell) && !is_impassable_grid_static[wall_cell.r][wall_cell.c]) {
                unbuilt_walls_count++;
            }
        }

        if (unbuilt_walls_count == 0) {
            human.objective = HumanObjective::STAYING_IN_SAFE_SPOT;
        } else {
            human.objective = HumanObjective::BUILDING_WALLS;
        }

        if(human.objective == HumanObjective::BUILDING_WALLS && human.turns_stuck_building >= MAX_STUCK_TURNS) {
            human.objective = HumanObjective::REPOSITIONING_STUCK; 
        }

        char chosen_action_for_human_i = '.';
        if (human.objective == HumanObjective::STAYING_IN_SAFE_SPOT) {
            chosen_action_for_human_i =
                move_to_best_terminal_component(human, tentative_walls_this_turn);
        } else if (human.objective == HumanObjective::GOING_TO_SAFE_SPOT ||
                   human.objective == HumanObjective::REPOSITIONING_STUCK) {
            if(human.objective == HumanObjective::REPOSITIONING_STUCK) human.turns_stuck_building = 0; 

            chosen_action_for_human_i = get_bfs_move_char(human.pos, human.final_stand_pos, tentative_walls_this_turn);

        } else if (human.objective == HumanObjective::BUILDING_WALLS) {
            Point best_wall_target = INVALID_POINT;
            Point best_stand_point = INVALID_POINT;
            int min_eval_score = INF;
            std::vector<std::vector<int>> distance_field =
                compute_distance_field(human.pos);

            for (const auto& wall_coord : human.assigned_wall_cells) {
                if (!is_valid_point(wall_coord) || is_impassable_grid_static[wall_coord.r][wall_coord.c]) continue;
                if (!can_theoretically_build_at(wall_coord, human.id)) continue;

                int adj_wall_bonus_val = count_adjacent_walls_or_boundaries(wall_coord) * ADJACENT_WALL_PRIORITY_BONUS;
                int current_near_pet_penalty = 0; // NEAR_PET_PENALTY_POINTS_PER_PET is 0

                for (int k_dir_idx = 0; k_dir_idx < 4; ++k_dir_idx) { 
                    Point potential_stand_pos = {wall_coord.r + DIRS[k_dir_idx].r, 
                                                 wall_coord.c + DIRS[k_dir_idx].c};

                    if (!is_valid_point(potential_stand_pos) || is_impassable_grid_static[potential_stand_pos.r][potential_stand_pos.c]) continue;

                    bool conflict_with_tentative_wall_build_spot = false; 
                    for(const auto& tw : tentative_walls_this_turn) { if(potential_stand_pos == tw) { conflict_with_tentative_wall_build_spot = true; break; }}
                    if(conflict_with_tentative_wall_build_spot) continue;

                    bool conflict_with_tentative_move_dest = false; 
                    for(int j=0; j < i; ++j) { 
                        if (tentative_move_targets_this_turn[j] == potential_stand_pos) { conflict_with_tentative_move_dest = true; break; }
                    }
                    if (conflict_with_tentative_move_dest) continue;

                    // Evaluate both the standing square and the wall square.
                    // The standing square cannot contain a pet, and wall cells
                    // close to pets are delayed to reduce interference with the
                    // unfinished separator.
                    bool pet_on_stand = false;
                    int nearest_pet_distance = INF;
                    int nearest_wall_pet_distance = INF;
                    for (const auto& pet : pets_global_state) {
                        int stand_distance = manhattan_distance(potential_stand_pos, pet.pos);
                        int wall_distance = manhattan_distance(wall_coord, pet.pos);
                        nearest_pet_distance = std::min(nearest_pet_distance, stand_distance);
                        nearest_wall_pet_distance = std::min(nearest_wall_pet_distance, wall_distance);
                        if (stand_distance == 0) {
                            pet_on_stand = true;
                            break;
                        }
                    }
                    if (pet_on_stand) continue;

                    int current_dist_to_stand =
                        distance_field[potential_stand_pos.r][potential_stand_pos.c];
                    if (current_dist_to_stand == INF) continue;

                    int current_eval_score =
                        current_dist_to_stand - adj_wall_bonus_val +
                        current_near_pet_penalty;

                    // Prefer construction positions with more clearance from pets.
                    if (nearest_pet_distance == 1) current_eval_score += 8;
                    else if (nearest_pet_distance == 2) current_eval_score += 2;

                    // A wall near a pet is more likely to be compromised before
                    // the complete separator is finished.
                    if (nearest_wall_pet_distance == 2) current_eval_score += 10;
                    else if (nearest_wall_pet_distance == 3) current_eval_score += 3;

                    bool is_inside_inner_safe_region = 
                        (potential_stand_pos.r >= human.inner_safe_ul.r &&
                         potential_stand_pos.r <= human.inner_safe_br.r &&
                         potential_stand_pos.c >= human.inner_safe_ul.c &&
                         potential_stand_pos.c <= human.inner_safe_br.c);

                    if (!is_inside_inner_safe_region) {
                        current_eval_score += STAND_OUTSIDE_INNER_SAFE_PENALTY; 
                    }

                    if (current_eval_score < min_eval_score) {
                        min_eval_score = current_eval_score;
                        best_wall_target = wall_coord;
                        best_stand_point = potential_stand_pos;
                    } else if (current_eval_score == min_eval_score) { 
                        if (best_wall_target.r == -1 || 
                            wall_coord < best_wall_target ||
                            (wall_coord == best_wall_target && potential_stand_pos < best_stand_point)) {
                            best_wall_target = wall_coord;
                            best_stand_point = potential_stand_pos;
                        }
                    }
                }
            }

            if (best_wall_target.r != -1) { 
                human.turns_stuck_building = 0; 
                if (human.pos == best_stand_point) { 
                    for(int k_dir=0; k_dir<4; ++k_dir){ 
                        if(human.pos.r + DIRS[k_dir].r == best_wall_target.r && 
                           human.pos.c + DIRS[k_dir].c == best_wall_target.c){
                            chosen_action_for_human_i = DIR_CHARS_BUILD[k_dir];
                            break;
                        }
                    }
                } else { 
